operations.content:
/* ==========================================================
   Full action submenu
   ========================================================== */

.frame-helm-full-budget {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.5rem;
}

.frame-helm-full-budget > div {
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
  border: 1px solid var(--color-border-light-2, #7a7971);
  border-radius: 4px;
  padding: 0.5rem;
}

.frame-helm-full-budget span {
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  opacity: 0.65;
}

.frame-helm-full-budget strong {
  font-size: 0.88rem;
}

.frame-helm-full-choice {
  min-height: 3.8rem;
}

.frame-helm-full-detail {
  display: flex;
  flex-direction: column;
  gap: 0.7rem;
  border: 1px solid var(--color-border-light-2, #7a7971);
  border-radius: 5px;
  padding: 0.75rem;
}

.frame-helm-full-detail-header {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
}

.frame-helm-full-detail-header > i {
  flex: 0 0 2rem;
  width: 2rem;
  margin-top: 0.1rem;
  font-size: 1.5rem;
  text-align: center;
}

.frame-helm-full-detail-header > div {
  min-width: 0;
}

.frame-helm-full-detail-header h3 {
  margin: 0;
  font-size: 1.15rem;
}

.frame-helm-full-detail-header p {
  margin: 0.2rem 0 0;
  font-size: 0.8rem;
  line-height: 1.3;
  opacity: 0.75;
}

.frame-helm-full-requirement {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  border: 1px dashed var(--color-border-light-2, #7a7971);
  border-radius: 4px;
  padding: 0.55rem;
  font-size: 0.75rem;
  line-height: 1.3;
}

.frame-helm-full-requirement > i {
  flex: 0 0 1.3rem;
  width: 1.3rem;
  font-size: 1rem;
  text-align: center;
}

.frame-helm-full-execute-button {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  width: 100%;
  min-height: 3.5rem;
  margin: 0;
  padding: 0.55rem 0.65rem;
  text-align: left;
}

.frame-helm-full-execute-button > i {
  flex: 0 0 1.7rem;
  width: 1.7rem;
  font-size: 1.15rem;
  text-align: center;
}

.frame-helm-full-execute-button > span {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
}

.frame-helm-full-execute-button strong {
  font-size: 0.92rem;
}

.frame-helm-full-execute-button small {
  margin-top: 0.1rem;
  font-size: 0.72rem;
  line-height: 1.25;
  opacity: 0.7;
}

.frame-helm-full-execute-button:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

.frame-helm-full-placeholder-note {
  margin: 0;
  font-size: 0.7rem;
  font-style: italic;
  line-height: 1.3;
  opacity: 0.65;
}

@media (max-width: 500px) {
  .frame-helm-full-budget {
    grid-template-columns: 1fr;
  }
}
